function hydrateIcons(scope=document){scope.querySelectorAll('[data-icon]').forEach(el=>{const name=el.dataset.icon;el.outerHTML=el.closest('.dock')&&DOCK_SOLID[name]?icon(name,'icon-outline')+dockSolid(name):icon(name);});}

